const { logger } = require('../shared-lib');

/**
 * Knowledge Set scope of a chat turn, sent to chatqna as `context.kbFileIds`.
 * chatqna reads a missing or empty list as "do not scope" (search every document)
 * and a non-empty list as the only files whose documents it may keep.
 */

/**
 * Scope entry that matches no file. Real file ids are generated by the document
 * repository and never take this form, so chatqna's Knowledge Set post-filter
 * keeps no document.
 */
const NO_KNOWLEDGE_SET_FILE_ID = '__no_knowledge_set__';

/** Values of EMPTY_KNOWLEDGE_SET_SCOPE: what a Topic Module without a Knowledge Set searches. */
const EMPTY_KNOWLEDGE_SET_SCOPES = Object.freeze({
  NONE: 'none',
  // Every document, as before this setting existed.
  ALL: 'all'
});

let warnedValue = null;

/**
 * Read EMPTY_KNOWLEDGE_SET_SCOPE. Unset, blank or unknown values mean NONE; an
 * unknown value is logged once.
 *
 * @param {object} [env]
 * @returns {string} one of EMPTY_KNOWLEDGE_SET_SCOPES
 */
function readEmptyKnowledgeSetScope(env = process.env) {
  const value = String(env.EMPTY_KNOWLEDGE_SET_SCOPE || '')
    .trim()
    .toLowerCase();
  if (value === EMPTY_KNOWLEDGE_SET_SCOPES.ALL) return EMPTY_KNOWLEDGE_SET_SCOPES.ALL;
  if (value && value !== EMPTY_KNOWLEDGE_SET_SCOPES.NONE && value !== warnedValue) {
    warnedValue = value;
    logger.warn(
      `EMPTY_KNOWLEDGE_SET_SCOPE="${value}" is not "${EMPTY_KNOWLEDGE_SET_SCOPES.NONE}" or ` +
        `"${EMPTY_KNOWLEDGE_SET_SCOPES.ALL}"; using "${EMPTY_KNOWLEDGE_SET_SCOPES.NONE}"`
    );
  }
  return EMPTY_KNOWLEDGE_SET_SCOPES.NONE;
}

/**
 * File ids for `context.kbFileIds`.
 *
 * @param {{ linkedKbFileIds?: string[] } | null} twin  the session's twin; null when
 *   the session has no twin or the lookup failed
 * @param {string} emptyScope  from readEmptyKnowledgeSetScope()
 * @returns {string[]}
 */
function knowledgeSetScope(twin, emptyScope) {
  // No twin to read a Knowledge Set from: retrieve unscoped, matching behaviour
  // before the Knowledge Set was wired up. Scoping to nothing on a failed lookup
  // would abstain on every question.
  if (!twin) return [];
  const fileIds = Array.isArray(twin.linkedKbFileIds) ? twin.linkedKbFileIds : [];
  if (fileIds.length > 0) return fileIds;
  return emptyScope === EMPTY_KNOWLEDGE_SET_SCOPES.ALL ? [] : [NO_KNOWLEDGE_SET_FILE_ID];
}

module.exports = {
  NO_KNOWLEDGE_SET_FILE_ID,
  EMPTY_KNOWLEDGE_SET_SCOPES,
  readEmptyKnowledgeSetScope,
  knowledgeSetScope
};
